<?php
require '../config/database.php';
if (empty($_SESSION['admin_id'])) { header('Location: login.php'); exit; }
$counts = [
    'customers' => (int) $conn->query("SELECT COUNT(*) FROM users WHERE role = 'customer'")->fetchColumn(),
    'orders' => (int) $conn->query('SELECT COUNT(*) FROM orders')->fetchColumn(),
    'reservations' => (int) $conn->query("SELECT COUNT(*) FROM reservations WHERE status = 'Pending'")->fetchColumn(),
    'revenue' => (float) $conn->query("SELECT COALESCE(SUM(total_price),0) FROM orders WHERE status <> 'Cancelled'")->fetchColumn(),
];
$latestOrders = $conn->query('SELECT o.id,o.total_price,o.status,o.created_at,u.full_name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC LIMIT 6')->fetchAll();
$latestReservations = $conn->query('SELECT customer_name,guests,reservation_at,status FROM reservations ORDER BY id DESC LIMIT 6')->fetchAll();
include '../includes/header.php';
?>
<style>body{background:#f6f4f1}.admin-shell{min-height:100vh}.admin-side{background:#241a15;min-height:100vh}.admin-side a{color:#f5eee8;text-decoration:none}.admin-side a:hover{color:#dfb78b}.metric-card{border:0;border-radius:1rem;box-shadow:0 8px 24px #25190e0d}</style>
<div class="container-fluid admin-shell"><div class="row"><aside class="col-md-3 col-xl-2 admin-side text-white p-4"><a href="index.php" class="h4 d-block mb-4">Brew Haven</a><p class="small text-white-50">ADMINISTRATION</p><nav class="d-grid gap-3"><a href="index.php">Overview</a><a href="products.php">Products</a><a href="../index.php">View storefront</a><form method="post" action="logout.php"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button class="btn btn-link p-0 text-white text-decoration-none" type="submit">Sign out</button></form></nav></aside><main class="col-md-9 col-xl-10 p-4 p-lg-5"><div class="d-flex justify-content-between align-items-center mb-4"><div><p class="text-muted mb-1">Overview</p><h1 class="h2">Welcome, <?= e($_SESSION['admin_name'] ?? 'Admin') ?></h1></div><span class="badge text-bg-light">Brew Haven Admin</span></div><div class="row g-3 mb-5"><?php foreach (['customers'=>'Customers','orders'=>'Orders','reservations'=>'Pending reservations','revenue'=>'Revenue'] as $key=>$label): ?><div class="col-sm-6 col-xl-3"><section class="card metric-card h-100"><div class="card-body"><p class="text-muted mb-2"><?= e($label) ?></p><p class="h3 mb-0"><?= $key === 'revenue' ? '৳'.number_format($counts[$key],2) : number_format($counts[$key]) ?></p></div></section></div><?php endforeach; ?></div><div class="row g-4"><section class="col-xl-7"><div class="card metric-card"><div class="card-body"><h2 class="h5 mb-3">Latest orders</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach ($latestOrders as $order): ?><tr><td>#<?= (int) $order['id'] ?><br><small class="text-muted"><?= e($order['created_at']) ?></small></td><td><?= e($order['full_name']) ?></td><td>৳<?= number_format((float) $order['total_price'],2) ?></td><td><?= e($order['status']) ?></td></tr><?php endforeach; ?><?php if (!$latestOrders): ?><tr><td colspan="4" class="text-muted">No orders yet.</td></tr><?php endif; ?></tbody></table></div></div></div></section><section class="col-xl-5"><div class="card metric-card"><div class="card-body"><h2 class="h5 mb-3">Latest reservations</h2><?php foreach ($latestReservations as $reservation): ?><div class="border-bottom py-2"><strong><?= e($reservation['customer_name']) ?></strong><span class="float-end small"><?= (int) $reservation['guests'] ?> guests</span><div class="small text-muted"><?= e($reservation['reservation_at']) ?> · <?= e($reservation['status']) ?></div></div><?php endforeach; ?><?php if (!$latestReservations): ?><p class="text-muted">No reservations yet.</p><?php endif; ?></div></div></section></div></main></div></div>
